  .np-card{
    max-width:780px; width:780px;
  }
  .np-art{
    width:460px; height:460px; border-radius:16px; overflow:hidden; box-shadow:var(--shadow);
    margin:0 auto 18px;
  }
  .np-art img{ width:460px; height:460px; display:block}
  .np-meta{
    display:flex; align-items:center; justify-content:space-between; gap:12px;
    color:#fff; opacity:.95; margin-bottom:10px;
