  .np-title{ font-weight:700 }
  .np-sub{ color:#e7d7e2 }
  .np-actions{ display:flex; align-items:center; gap:12px}
  .np-actions .btn{ width:34px; height:34px; display:grid; place-items:center; border-radius:8px; background:rgba(255,255,255,.12)}
  .np-actions .btn:hover{ background:rgba(255,255,255,.22)}
  .np-progress{
    margin:10px 0 18px;
  }
  .np-time{ display:flex; justify-content:space-between; font-size:12px; color:#f3e9ef; margin-bottom:6px}
  .np-range{ width:100% }
  input[type=range]{
    -webkit-appearance:none; appearance:none; height:4px; background:rgba(255,255,255,.35); border-radius:99px; outline:none;
  }
  input[type=range]::-webkit-slider-thumb{
    -webkit-appearance:none; appearance:none; width:12px; height:12px; background:#fff; border-radius:50%;
    border:2px solid #fff; margin-top:-4px;
  }
  .np-controls{
    display:flex; align-items:center; justify-content:center; gap:22px; margin-top:8px;
  }
  .np-controls .btn{
    width:42px; height:42px; display:grid; place-items:center; border-radius:50%;
    background:rgba(255,255,255,.14); cursor:pointer;
  }
  .np-controls .btn:hover{ background:rgba(255,255,255,.22)}
  .flip-x{ transform:scaleX(-1)}
  .hidden{ display:none !important}
  .pill{
    display:inline-block; background:#d91c49; color:#fff; font-size:10px; font-weight:800; padding:3px 6px; border-radius:4px; margin-left:6px;
  }

  /* Buttons recognition class (already used where appropriate) */
  .btn{ cursor:pointer }

  /* Utility for icon sizing */
  .ico{ width:18px; height:18px; display:block }
  .ico24{ width:24px;height:24px; display:block }

  /* Scrollbar subtle */
  .main::-webkit-scrollbar{ width:10px}
  .main::-webkit-scrollbar-thumb{ background:#d66; border-radius:99px}
</style>
</head>
